def text(key, language='en'):
    return ROWS.get(key, ROWS['failed'])[CODES.index(language) if language in CODES else 1]


def install_catalogue():
    from jarvis.i18n import EXACT
    for translations in ROWS.values():
        EXACT[translations[0]] = dict(zip(CODES[1:], translations[1:]))


def diagnostic_text(failure,language='en'):
    if not isinstance(failure,dict):return ''
    from .diagnostics import STAGES,CODES,CATEGORIES
    stage=failure.get('stage')
    if stage not in STAGES:return ''
    category=failure.get('category')
    code=category if category in CATEGORIES and category!='unknown' else failure.get('code')
    if code not in CODES and code not in CATEGORIES:return ''
    parts=[]
    for key,label in (('http_status','HTTP'),('errno','errno'),('winerror','WinError'),('returncode','exit')):
        value=failure.get(key)
        if type(value) is int and -(2**31)<=value<2**32:parts.append(f'{label} {value}')
    details=' ('+', '.join(parts)+')' if parts else ''
    return text('diagnostic_detail',language).format(stage=stage,code=code,details=details)
